AgentFramework use #2. Because it allow inject on demand. for example:

```typescript

class ServiceA {
    run() {}
}
class ServiceB {
    run() {}
}

class App {
    @singleton()
    a!: ServiceA

    @singleton()
    b!: ServiceB

    firstStep() {
        this.a.run()
    }

    secondStep() {
        this.b.run()
    }
}

